pdfjsLib.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";const dropZone=document.getElementById("drop-zone"),fileInput=document.getElementById("file-input"),loading=document.getElementById("loading"),viewer=document.getElementById("viewer"),pagesContainer=document.getElementById("pdf-pages"),keywords=["definition","important","key","remember","exam","note","summary","essential","focus"];async function processFile(e){if(e){dropZone.style.display="none",loading.style.display="block";try{const t=await e.arrayBuffer(),n=await pdfjsLib.getDocument(t).promise;pagesContainer.innerHTML="",viewer.style.display="block";for(let e=1;e<=n.numPages;e++)await renderPageWithHighlights(n,e);loading.style.display="none",setTimeout(()=>{window.print()},2e3)}catch(e){alert("Error rendering PDF."),location.reload()}}}async function renderPageWithHighlights(e,t){const n=await e.getPage(t),i=n.getViewport({scale:1.5}),o=document.createElement("div");o.className="pdf-page-wrapper";const a=document.createElement("canvas"),r=a.getContext("2d");a.height=i.height,a.width=i.width,o.appendChild(a),pagesContainer.appendChild(o),await n.render({canvasContext:r,viewport:i}).promise;const s=await n.getTextContent(),l=document.createElement("canvas");l.className="highlight-overlay",l.width=i.width,l.height=i.height;const d=l.getContext("2d");o.appendChild(l),s.items.forEach(e=>{const t=e.str.toLowerCase();if((keywords.some(e=>t.includes(e))||t.includes(":")||t.length>20&&t.match(/[A-Z]{2,}/))&&t.trim().length>3){const t=pdfjsLib.Util.transform(i.transform,e.transform);d.fillStyle="rgba(255, 255, 0, 0.35)",d.fillRect(t[4],t[5]-e.height,e.width,1.2*e.height)}})}dropZone.onclick=()=>fileInput.click(),fileInput.onchange=e=>processFile(e.target.files[0]);